UPDATE ProductionPlan.Machines SET FromMonth = '2026-05-01' WHERE MachineID = 8 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-02-01' WHERE MachineID = 87 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-02-01' WHERE MachineID = 90 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-02-01' WHERE MachineID = 93 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-09-01' WHERE MachineID = 94 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-04-01' WHERE MachineID = 135 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-05-01' WHERE MachineID = 137 AND FromMonth IS NULL AND ToMonth IS NULL;
UPDATE ProductionPlan.Machines SET FromMonth = '2026-03-01' WHERE MachineID = 145 AND FromMonth IS NULL AND ToMonth IS NULL;
