UPDATE ProductionPlan.Machines SET FromMonth = '2026-03-01' WHERE MachineID = 154 AND FromMonth IS NULL AND ToMonth IS NULL;
-- 2) PART A (คลัง FG) / PART B (คลัง SUB) ที่ยังไม่มี -> เพิ่มเฉพาะ CHR-Nexus (ชื่อตาม Excel)
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @fg WHERE LTRIM(RTRIM(p.PartA)) = N'A000-00000')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @fg WHERE LTRIM(RTRIM(p.PartA)) = N'A265-00014')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @fg WHERE LTRIM(RTRIM(p.PartA)) = N'A958-00009')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B148-00026' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B148-00026')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B148-00033' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B148-00033')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B148-00095' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B148-00095')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B203-00002' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B203-00002')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B203-00003' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B203-00003')
BEGIN
END
IF NOT EXISTS (SELECT 1 FROM Nexus.Parts p WHERE LTRIM(RTRIM(p.PartCode)) = N'B396-00001' OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = N'B396-00001')
BEGIN
END
DECLARE @np TABLE (K INT PRIMARY KEY, Dept NVARCHAR(20), MID INT NULL, Code NVARCHAR(50) NULL, A NVARCHAR(60), B NVARCHAR(60), PCode NVARCHAR(200), TP DECIMAL(9,3), Col DECIMAL(9,3), CT DECIMAL(9,3), Man DECIMAL(9,2), F DATE, T DATE, ItemID INT NULL);
UPDATE n SET MID = m.MachineID FROM @np n JOIN ProductionPlan.Machines m ON m.Dept = n.Dept AND m.MachineCode = n.Code WHERE n.MID IS NULL;
-- แถวที่เคยเพิ่มแล้ว (รันซ้ำ) = ใช้แถวเดิม
UPDATE n SET ItemID = x.ItemID FROM @np n JOIN ProductionPlan.MachineParts x ON x.MachineID = n.MID AND x.SortNo = 1000 + n.K AND x.CreatedBy = @by;
SELECT n.MID, 1000 + n.K, a.PartID, COALESCE(b.PartID, ab.PartID), n.PCode, n.TP, n.Col, n.CT, n.Man, 1, @by, @by, n.F, n.T
FROM @np n
CROSS APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @fg WHERE LTRIM(RTRIM(p.PartA)) = n.A ORDER BY p.PartID) a
OUTER APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @sub WHERE n.B <> n.A AND (LTRIM(RTRIM(p.PartCode)) = n.B OR LTRIM(RTRIM(ISNULL(p.PartB, N''))) = n.B) ORDER BY p.PartID) b
OUTER APPLY (SELECT TOP 1 p.PartID FROM Nexus.Parts p JOIN Nexus.PartStocks s ON s.PartID = p.PartID AND s.StockID = @fg WHERE LTRIM(RTRIM(p.PartA)) = n.B ORDER BY p.PartID) ab
WHERE n.ItemID IS NULL AND n.MID IS NOT NULL;
DECLARE @rc INT = @@ROWCOUNT, @tot INT = (SELECT COUNT(*) FROM @np);
PRINT N'แถว Product ใหม่: ' + CAST(@rc AS NVARCHAR(10)) + N' / ' + CAST(@tot AS NVARCHAR(10));
UPDATE n SET ItemID = x.ItemID FROM @np n JOIN ProductionPlan.MachineParts x ON x.MachineID = n.MID AND x.SortNo = 1000 + n.K AND x.CreatedBy = @by WHERE n.ItemID IS NULL;
