DECLARE @act TABLE (Dept NVARCHAR(20), MID INT NULL, Code NVARCHAR(50) NULL, D DATE, Hr DECIMAL(6,2), Stroke DECIMAL(12,2), Man DECIMAL(6,2));
UPDATE a SET MID = m.MachineID FROM @act a JOIN ProductionPlan.Machines m ON m.Dept = a.Dept AND m.MachineCode = a.Code WHERE a.MID IS NULL;
SELECT a.MID, a.D, a.Hr, a.Stroke, a.Man, @by FROM @act a
WHERE a.MID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ProductionPlan.DailyActuals x WHERE x.MachineID = a.MID AND x.WorkDate = a.D);
SELECT @rc = @@ROWCOUNT, @tot = (SELECT COUNT(*) FROM @act);
PRINT N'Actual รายวัน: เพิ่ม ' + CAST(@rc AS NVARCHAR(10)) + N' / Excel ' + CAST(@tot AS NVARCHAR(10)) + N' (วันที่มีอยู่แล้ว = ไม่แตะ)';
DECLARE @pcs TABLE (M DATE, ItemID INT NULL, K INT NULL, Pcs DECIMAL(14,2));
UPDATE p SET ItemID = n.ItemID FROM @pcs p JOIN @np n ON n.K = p.K WHERE p.ItemID IS NULL;
-- PCS อัตโนมัติ (Order > 0 = Order · ไม่มี = Forecast) แบบเดียวกับหน้าเว็บ -> เก็บเฉพาะที่ Excel ต่าง
;WITH dm AS (
    SELECT DATEFROMPARTS(YEAR(TargetDate), MONTH(TargetDate), 1) AS M, LTRIM(RTRIM(PartACode)) AS A, SUM(ISNULL(ForecastQuantity, 0)) AS F, SUM(ISNULL(OrderQuantity, 0)) AS O
    FROM Nexus.ForecastOrderImports WITH (NOLOCK) WHERE TargetDate >= '2026-01-01' AND TargetDate < '2026-12-01' AND ISNULL(PartACode, '') <> ''
    GROUP BY DATEFROMPARTS(YEAR(TargetDate), MONTH(TargetDate), 1), LTRIM(RTRIM(PartACode)))
SELECT p.M, p.ItemID, p.Pcs, @by
FROM @pcs p
JOIN ProductionPlan.MachineParts x ON x.ItemID = p.ItemID
JOIN Nexus.Parts a ON a.PartID = x.PartAID
LEFT JOIN dm ON dm.M = p.M AND dm.A = LTRIM(RTRIM(a.PartA))
WHERE p.Pcs <> CASE WHEN ISNULL(dm.O, 0) > 0 THEN dm.O WHEN ISNULL(dm.F, 0) > 0 THEN dm.F ELSE 0 END
  AND NOT EXISTS (SELECT 1 FROM ProductionPlan.PcsOverrides o WHERE o.MonthStart = p.M AND o.ItemID = p.ItemID);
PRINT N'PCS ตาม Excel (ต่างจาก Order / Forecast): ' + CAST(@@ROWCOUNT AS NVARCHAR(10)) + N' แถว-เดือน';
-- 5) แผนของเดือนตาม Excel (P1 = ตารางสรุปของหน่วยงาน · C3 / C2 / C4 / P7 = ตาราง Condition ของชีทเครื่อง) · มีแล้ว = ไม่แตะ
DECLARE @mp TABLE (Dept NVARCHAR(20), MID INT NULL, Code NVARCHAR(50) NULL, M DATE, P1 DECIMAL(18,4), C3 DECIMAL(18,6), Qty DECIMAL(9,2), Eff DECIMAL(6,4), Man DECIMAL(9,2), Src NVARCHAR(200));
UPDATE p SET MID = m.MachineID FROM @mp p JOIN ProductionPlan.Machines m ON m.Dept = p.Dept AND m.MachineCode = p.Code WHERE p.MID IS NULL;
SELECT p.M, p.MID, p.P1, p.C3, p.Qty, p.Eff, p.Man, p.Src, @by FROM @mp p
WHERE p.MID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ProductionPlan.MonthPlans x WHERE x.MonthStart = p.M AND x.MachineID = p.MID);
SELECT @rc = @@ROWCOUNT, @tot = (SELECT COUNT(*) FROM @mp);
PRINT N'แผนตาม Excel: ' + CAST(@rc AS NVARCHAR(10)) + N' / ' + CAST(@tot AS NVARCHAR(10)) + N' เครื่อง-เดือน';
